@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[const Text('Settings',style:TextStyle(fontSize:30,fontWeight:FontWeight.w700)),const Text('Your personal data stays on this device.',style:TextStyle(color:muted)),ListTile(title:const Text('Configure public content URL'),leading:const Icon(Icons.link),onTap:_configure),Text(status,style:const TextStyle(color:muted)),FilledButton.tonalIcon(onPressed:_refresh,icon:const Icon(Icons.refresh),label:const Text('Check for updates')),const Divider(height:30),const Text('Privacy & data',style:TextStyle(fontWeight:FontWeight.w700)),const Text('No account, backend, Firebase or cloud sync. Birth details, journal, favorites and preferences are not sent to content hosts.'),OutlinedButton.icon(onPressed:_delete,icon:const Icon(Icons.delete_outline),label:const Text('Delete local personal data')),const SizedBox(height:20),const Text(disclaimer,style:TextStyle(color:muted)),const Text('Light appearance only. No dark theme or theme switch.',style:TextStyle(color:muted))]);
Future<void> _configure()async{final c=TextEditingController(text:url??'');final v=await showDialog<String>(context:context,builder:(_)=>AlertDialog(title:const Text('Public JSON URL'),content:TextField(controller:c),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,c.text.trim()),child:const Text('Save'))]));if(v!=null){await LocalDb.instance.setting('url',v);setState(()=>url=v);}}
Future<void> _refresh()async{if(url==null||url!.isEmpty){setState(()=>status='Configure a public JSON URL first.');return;}setState(()=>status='Checking…');try{final r=await http.get(Uri.parse(url!)).timeout(const Duration(seconds:12));if(r.statusCode!=200||r.bodyBytes.length>524288)throw Exception('Request failed or exceeds 512 KB');final j=jsonDecode(r.body);if(j is! Map<String,dynamic>||j['schema_version']!=1)throw Exception('Unsupported schema');await LocalDb.instance.setting('remote_cache',r.body);setState(()=>status='Content validated and cached.');}catch(e){setState(()=>status='Update unavailable; prior content remains. '+e.toString());}}
Future<void> _delete()async{final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Delete local data?'),content:const Text('This permanently removes favorites, journal and local settings.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Delete'))]));if(ok==true){await LocalDb.instance.clear();widget.onChanged();setState(()=>status='Local data deleted.');}}
}
